package theme

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"charm.land/lipgloss/v2"
)

// ContrastRatio returns the WCAG 2.x contrast ratio (1 to 21) between two
// colors written as #rgb or #rrggbb (case-insensitive). Any other form is an
// error. The ratio is symmetric: (L1+0.05)/(L2+0.05) with L1 the lighter.
func ContrastRatio(fg, bg lipgloss.Color) (float64, error) {
	lf, err := relativeLuminance(fg)
	if err != nil {
		return 0, err
	}
	lb, err := relativeLuminance(bg)
	if err != nil {
		return 0, err
	}
	if lf < lb {
		lf, lb = lb, lf
	}
	return (lf + 0.05) / (lb + 0.05), nil
}

// relativeLuminance computes the WCAG relative luminance of an sRGB color.
func relativeLuminance(c lipgloss.Color) (float64, error) {
	s := string(c)
	if !strings.HasPrefix(s, "#") {
		return 0, fmt.Errorf("contrast: %q is not a #rgb or #rrggbb color", s)
	}
	h := s[1:]
	if len(h) == 3 {
		h = string([]byte{h[0], h[0], h[1], h[1], h[2], h[2]})
	}
	if len(h) != 6 {
		return 0, fmt.Errorf("contrast: %q is not a #rgb or #rrggbb color", s)
	}
	var ch [3]float64
	for i := range ch {
		v, err := strconv.ParseUint(h[i*2:i*2+2], 16, 8)
		if err != nil {
			return 0, fmt.Errorf("contrast: %q is not a #rgb or #rrggbb color", s)
		}
		f := float64(v) / 255
		if f <= 0.03928 {
			ch[i] = f / 12.92
		} else {
			ch[i] = math.Pow((f+0.055)/1.055, 2.4)
		}
	}
	return 0.2126*ch[0] + 0.7152*ch[1] + 0.0722*ch[2], nil
}
package theme

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"charm.land/lipgloss/v2"
)

// TokenRole is what a segment of the token-mix bar counts. Like IconRole it is
// a meaning, so a theme can have an opinion about it and a view only names it.
type TokenRole string

const (
	TokenRoleInput      TokenRole = "input"
	TokenRoleOutput     TokenRole = "output"
	TokenRoleCacheWrite TokenRole = "cache-write"
	TokenRoleCacheRead  TokenRole = "cache-read"
)

// TokenRoles lists the roles in bar order (Input, Output, Cache write, Cache read).
func TokenRoles() []TokenRole {
	return []TokenRole{TokenRoleInput, TokenRoleOutput, TokenRoleCacheWrite, TokenRoleCacheRead}
}

// TokenColor is the colour a role is painted in.
//
// An unrecognised role falls back to the ordinary text colour rather than to
// the zero Color, for the same reason IconColor does: an empty colour inherits
// whatever the terminal last emitted (Rule 122).
func TokenColor(role TokenRole) lipgloss.Color {
	switch role {
	case TokenRoleInput:
		return ColorTokenInput
	case TokenRoleOutput:
		return ColorTokenOutput
	case TokenRoleCacheWrite:
		return ColorTokenCacheWrite
	case TokenRoleCacheRead:
		return ColorTokenCacheRead
	}
	return ColorText
}

// TokenStyle is the foreground-only style of a role; datatable and the bar
// supply the background themselves (Rule 122).
func TokenStyle(role TokenRole) lipgloss.Style {
	return lipgloss.NewStyle().Foreground(TokenColor(role))
}

// ColorDistance is the CIE76 delta E between two hex colours, in Lab (D65).
// Colours are #rgb or #rrggbb; anything else is an error.
func ColorDistance(a, b lipgloss.Color) (float64, error) {
	la, err := hexToLab(a)
	if err != nil {
		return 0, err
	}
	lb, err := hexToLab(b)
	if err != nil {
		return 0, err
	}
	dl, da, db := la[0]-lb[0], la[1]-lb[1], la[2]-lb[2]
	return math.Sqrt(dl*dl + da*da + db*db), nil
}

// hexToLab converts a #rgb or #rrggbb colour to CIE Lab with a D65 white point.
func hexToLab(c lipgloss.Color) ([3]float64, error) {
	s := string(c)
	h := strings.TrimPrefix(s, "#")
	if h == s {
		return [3]float64{}, fmt.Errorf("color distance: %q is not a #rgb or #rrggbb color", s)
	}
	if len(h) == 3 {
		h = string([]byte{h[0], h[0], h[1], h[1], h[2], h[2]})
	}
	if len(h) != 6 {
		return [3]float64{}, fmt.Errorf("color distance: %q is not a #rgb or #rrggbb color", s)
	}
	var lin [3]float64
	for i := range lin {
		v, err := strconv.ParseUint(h[i*2:i*2+2], 16, 8)
		if err != nil {
			return [3]float64{}, fmt.Errorf("color distance: %q is not a #rgb or #rrggbb color", s)
		}
		f := float64(v) / 255
		if f <= 0.04045 {
			lin[i] = f / 12.92
		} else {
			lin[i] = math.Pow((f+0.055)/1.055, 2.4)
		}
	}
	x := (0.4124564*lin[0] + 0.3575761*lin[1] + 0.1804375*lin[2]) / 0.95047
	y := 0.2126729*lin[0] + 0.7151522*lin[1] + 0.0721750*lin[2]
	z := (0.0193339*lin[0] + 0.1191920*lin[1] + 0.9503041*lin[2]) / 1.08883
	fx, fy, fz := labF(x), labF(y), labF(z)
	return [3]float64{116*fy - 16, 500 * (fx - fy), 200 * (fy - fz)}, nil
}

func labF(t float64) float64 {
	const delta = 6.0 / 29.0
	if t > delta*delta*delta {
		return math.Cbrt(t)
	}
	return t/(3*delta*delta) + 4.0/29.0
}
package theme

import "charm.land/lipgloss/v2"

// IconRole is what a glyph *means*, which is the only thing a palette can have
// an opinion about.
//
// The alternative was a table keyed on the glyph itself. It was rejected for a
// reason worth writing down: a codepoint is a value, not a name, so
// `U+F0849 -> ColorSecondary` cannot be read in review — nothing on the line
// says whether the entry is right, and a wrong one is indistinguishable from a
// deliberate one. A role is a word, so it can be argued with.
//
// It is the shape ForgeIcon, SeverityTextStyle and CIScoreStyle already have:
// the caller names a meaning, the theme answers with a colour.
type IconRole string

const (
	// The explorer's two node kinds. They are named for the model rather than
	// for either forge's wording — a GitLab group and a GitHub organisation are
	// one role, which is exactly what forge.Vocabulary exists to say.
	IconRoleNamespace  IconRole = "namespace"
	IconRoleRepository IconRole = "repository"

	// The three visibilities. GitHub has no internal, so the role simply never
	// resolves there; a role with no rows is cheaper than a second table.
	IconRoleVisPublic   IconRole = "vis-public"
	IconRoleVisInternal IconRole = "vis-internal"
	IconRoleVisPrivate  IconRole = "vis-private"

	// What the workspaces and :sec listings hold. IconRoleRepository above is
	// reused for a git repository on disk rather than duplicated: a repository
	// is a repository, and one colour for it across three views is the point of
	// a role — the explorer's is remote and these are local, which is a
	// difference of location, not of kind.
	IconRoleDirectory IconRole = "directory"
	IconRoleFile      IconRole = "file"
	IconRoleImage     IconRole = "image"
	IconRoleContainer IconRole = "container"
)

// IconColor is the colour a role is painted in.
//
// An unrecognised role falls back to the ordinary text colour rather than to
// the zero Color: a zero lipgloss.Color is the empty string, which renders as
// "no colour set" and inherits whatever the terminal last emitted — the exact
// bleed Rule 122 is about. A role nobody declared should look like plain text,
// not like the row above it.
func IconColor(role IconRole) lipgloss.Color {
	switch role {
	case IconRoleNamespace:
		return ColorIconNamespace
	case IconRoleRepository:
		return ColorIconRepository
	case IconRoleVisPublic:
		return ColorIconVisPublic
	case IconRoleVisInternal:
		return ColorIconVisInternal
	case IconRoleVisPrivate:
		return ColorIconVisPrivate
	case IconRoleDirectory:
		return ColorIconDirectory
	case IconRoleFile:
		return ColorIconFile
	case IconRoleImage:
		return ColorIconImage
	case IconRoleContainer:
		return ColorIconContainer
	}
	return ColorText
}

// IconStyle is what a datatable column's Style function returns for an icon
// cell. Foreground only: datatable gives every unselected cell the application
// background itself, so naming one here would be a second answer to a question
// already settled (Rule 122).
func IconStyle(role IconRole) lipgloss.Style {
	return lipgloss.NewStyle().Foreground(IconColor(role))
}

