package theme

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// DEVDESK-201 step A2, H3: LoadTheme validates the hex values. A non-empty
// value that is not #rgb or #rrggbb refuses the whole theme, naming the key and
// the value; an empty optional value keeps today's fallback.
//
// These tests use only LoadTheme and DefaultTheme, so they are the ones that
// can be proven red on the v1 code (they are [R-assert]).

// isolateThemeHome points ThemeDir at a temp directory and returns it.
func isolateThemeHome(t *testing.T) string {
	t.Helper()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("USERPROFILE", home)
	dir := filepath.Join(home, ".devdesk", "themes")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

// writeThemeWith writes a complete, valid theme (the default one) with the
// given JSON keys overridden, and returns its name.
func writeThemeWith(t *testing.T, dir string, overrides map[string]string) string {
	t.Helper()
	raw, err := json.Marshal(DefaultTheme())
	if err != nil {
		t.Fatal(err)
	}
	m := map[string]any{}
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	for k, v := range overrides {
		m[k] = v
	}
	m["name"] = "under-test"
	data, err := json.Marshal(m)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "under-test.json"), data, 0o644); err != nil {
		t.Fatal(err)
	}
	return "under-test"
}

// [R-assert] on v1 too: LoadTheme does not validate today.
func TestLoadThemeRejectsAnInvalidHex(t *testing.T) {
	keys := []string{"color_ok", "color_background", "title_fg", "severity_critical_fg", "token_cache_read"}
	values := []string{"#ggg", "red", "12", "ffffff", "#12345"}
	for _, key := range keys {
		for _, value := range values {
			t.Run(key+"="+value, func(t *testing.T) {
				dir := isolateThemeHome(t)
				name := writeThemeWith(t, dir, map[string]string{key: value})

				got, err := LoadTheme(name)

				if err == nil {
					t.Fatalf("LoadTheme accepted %s = %q", key, value)
				}
				if got != nil {
					t.Errorf("LoadTheme returned a theme alongside the error: %+v", got)
				}
				if !strings.Contains(err.Error(), key) {
					t.Errorf("error %q does not name the key %q", err, key)
				}
				if !strings.Contains(err.Error(), `"`+value+`"`) {
					t.Errorf("error %q does not quote the value %q", err, value)
				}
			})
		}
	}
}

// Valid forms stay valid, upper case included: the validation must not be
// stricter than ContrastRatio, which accepts both lengths in either case.
func TestLoadThemeAcceptsShortAndUpperCaseHex(t *testing.T) {
	dir := isolateThemeHome(t)
	name := writeThemeWith(t, dir, map[string]string{"color_ok": "#0F0", "title_fg": "#ABCDEF"})
	if _, err := LoadTheme(name); err != nil {
		t.Fatalf("LoadTheme refused #0F0 / #ABCDEF: %v", err)
	}
}

// optionalThemeKeys returns the JSON key of every field tagged omitempty: the
// component colours that fall back to the semantic palette.
func optionalThemeKeys(t *testing.T) []string {
	t.Helper()
	var keys []string
	rt := reflect.TypeOf(Theme{})
	for i := 0; i < rt.NumField(); i++ {
		tag := rt.Field(i).Tag.Get("json")
		if name, opts, _ := strings.Cut(tag, ","); strings.Contains(opts, "omitempty") {
			keys = append(keys, name)
		}
	}
	if len(keys) < 30 {
		t.Fatalf("found only %d optional keys; the reflection no longer sees the omitempty tags", len(keys))
	}
	return keys
}

// [C] An empty optional value is today's fallback, not an error.
func TestLoadThemeKeepsEmptyOptionalKeys(t *testing.T) {
	dir := isolateThemeHome(t)
	empty := map[string]string{}
	for _, k := range optionalThemeKeys(t) {
		empty[k] = ""
	}
	name := writeThemeWith(t, dir, empty)

	th, err := LoadTheme(name)
	if err != nil {
		t.Fatalf("LoadTheme refused empty optional keys: %v", err)
	}
	if th.TitleFg != "" || th.TokenInput != "" {
		t.Errorf("empty optional values were rewritten: title_fg=%q token_input=%q", th.TitleFg, th.TokenInput)
	}
}

// [C] A key left out of the file is the same as an empty one.
func TestLoadThemeKeepsAbsentOptionalKeys(t *testing.T) {
	dir := isolateThemeHome(t)
	data := `{"name":"minimal","color_ok":"#00ff00","color_error":"#ff0000","color_warn":"#ff8800",` +
		`"color_primary":"#0000ff","color_secondary":"#8888ff","color_border":"#cccccc","color_text":"#000000",` +
		`"color_dim":"#888888","color_highlight":"#ffff00","color_white":"#ffffff","color_black":"#000000"}`
	if err := os.WriteFile(filepath.Join(dir, "minimal.json"), []byte(data), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadTheme("minimal"); err != nil {
		t.Fatalf("LoadTheme refused a theme without optional keys: %v", err)
	}
}

// [C] Guards H3 against the shipped files: none of them may be refused.
func TestEveryShippedThemeLoads(t *testing.T) {
	files, err := filepath.Glob("../../../themes/*.json")
	if err != nil || len(files) == 0 {
		t.Fatalf("no theme found under themes/*.json (err %v)", err)
	}
	dir := isolateThemeHome(t)
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dir, filepath.Base(f)), data, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	for _, f := range files {
		name := strings.TrimSuffix(filepath.Base(f), ".json")
		t.Run(name, func(t *testing.T) {
			if _, err := LoadTheme(name); err != nil {
				t.Errorf("shipped theme %s refused: %v", name, err)
			}
		})
	}
}
package theme

import (
	"image/color"
	"strings"
	"testing"

	"charm.land/bubbles/v2/textinput"
	"charm.land/lipgloss/v2"
)

// DEVDESK-201 step A2: the palette is color.Color, Hex replaces string(c), and
// the contrast code reads components through RGBA() after a type check.
//
// These tests use the v2 API (Hex, validateTheme, color.Color-typed
// applyColor, textinput.SetStyles), so they are [R-compile] until the
// production side of A2 lands.

// [R-compile] Hex undefined.
func TestHexFormatsAColor(t *testing.T) {
	tests := []struct {
		name string
		c    color.Color
		want string
	}{
		{"six digits", lipgloss.Color("#a1b2c3"), "#a1b2c3"},
		{"three digits are expanded", lipgloss.Color("#fff"), "#ffffff"},
		{"upper case is lowered", lipgloss.Color("#ABCDEF"), "#abcdef"},
		{"empty is no colour", lipgloss.Color(""), "none"},
		{"NoColor", lipgloss.NoColor{}, "none"},
		{"an ANSI index is not an RGBA", lipgloss.Color("12"), "none"},
		{"nil", nil, "none"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Hex(tt.c); got != tt.want {
				t.Errorf("Hex = %q, want %q", got, tt.want)
			}
		})
	}
}

// [R-compile] validateTheme undefined. The message format is the contract the
// callers log.
func TestValidateThemeNamesTheFirstBadKey(t *testing.T) {
	th := DefaultTheme()
	th.ColorOK = "#ggg"
	err := validateTheme(th)
	if err == nil {
		t.Fatal("validateTheme accepted color_ok = #ggg")
	}
	if want := `color_ok: "#ggg" is not #rgb or #rrggbb`; !strings.Contains(err.Error(), want) {
		t.Errorf("error = %q, want it to contain %q", err, want)
	}
}

func TestTheDefaultThemeIsValid(t *testing.T) {
	if err := validateTheme(DefaultTheme()); err != nil {
		t.Fatalf("DefaultTheme is refused by its own validation: %v", err)
	}
}

// [R-compile] applyColor takes and returns color.Color. Empty is the fallback.
func TestApplyColorFallsBackOnEmptyOnly(t *testing.T) {
	fallback := lipgloss.Color("#123456")
	if got := applyColor("", fallback); got != fallback {
		t.Errorf("applyColor(\"\") = %s, want the fallback %s", Hex(got), Hex(fallback))
	}
	if got := applyColor("#abcdef", fallback); Hex(got) != "#abcdef" {
		t.Errorf("applyColor(#abcdef) = %s, want #abcdef", Hex(got))
	}
}

// [C] on the semantics (spike criterion 2): an empty colour renders no SGR and
// an unknown icon role reads as plain text.
func TestAnEmptyColorRendersNoSGR(t *testing.T) {
	if got := lipgloss.NewStyle().Foreground(lipgloss.Color("")).Render("x"); got != "x" {
		t.Errorf("empty foreground rendered %q, want %q", got, "x")
	}
	if got := IconColor(IconRole("nope")); got != ColorText {
		t.Errorf("IconColor(unknown) = %s, want ColorText %s", Hex(got), Hex(ColorText))
	}
}

// [R-compile] The contrast code type-checks before reading components:
// NoColor.RGBA() is opaque black and would otherwise read as a real colour.
func TestContrastRejectsNonRGBAColors(t *testing.T) {
	white := lipgloss.Color("#ffffff")
	for name, c := range map[string]color.Color{
		"NoColor":    lipgloss.NoColor{},
		"empty":      lipgloss.Color(""),
		"ANSI index": lipgloss.Color("5"),
		"nil":        nil,
	} {
		t.Run(name, func(t *testing.T) {
			if _, err := ContrastRatio(c, white); err == nil {
				t.Errorf("ContrastRatio accepted %s as a foreground", name)
			}
			if _, err := ContrastRatio(white, c); err == nil {
				t.Errorf("ContrastRatio accepted %s as a background", name)
			}
			if _, err := ColorDistance(c, white); err == nil {
				t.Errorf("ColorDistance accepted %s", name)
			}
		})
	}
}

// [R-compile] StyleTextInput goes through SetStyles in v2 (the v1 fields
// TextStyle, PromptStyle, PlaceholderStyle and Cursor.Style are gone). The
// virtual cursor loses its background (Rule 115): that part is a manual check.
func TestStyleTextInputAppliesThemeColours(t *testing.T) {
	withTheme(t, separatedTheme())
	ti := textinput.New()
	ti.Prompt = "> "

	StyleTextInput(&ti)

	if ti.Prompt != "" {
		t.Errorf("Prompt = %q, want empty (Rule 120: the label is rendered outside)", ti.Prompt)
	}
	styles := ti.Styles()
	for name, state := range map[string]textinput.StyleState{"focused": styles.Focused, "blurred": styles.Blurred} {
		if got := state.Text.GetForeground(); got != ColorText {
			t.Errorf("%s text foreground = %s, want ColorText %s", name, Hex(got), Hex(ColorText))
		}
		if got := state.Text.GetBackground(); got != ColorBackground {
			t.Errorf("%s text background = %s, want the app background %s (Rule 115)", name, Hex(got), Hex(ColorBackground))
		}
		if got := state.Placeholder.GetForeground(); got != ColorDim {
			t.Errorf("%s placeholder foreground = %s, want ColorDim %s", name, Hex(got), Hex(ColorDim))
