78:	// lipgloss's Bold, Italic and Strikethrough over the ordinary text colour.

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Color returns the theme colour that paints s. The theme globals are read at
// call time because ApplyTheme reassigns them.
func Color(s State) lipgloss.Color {
	switch s {
	case Running:
		return theme.ColorActivityRunning
	case Failed:
		return theme.ColorActivityFailed
	case Suspended, Restarting:
		return theme.ColorActivitySuspended
	case Queued, Done, Cancelled, Skipped, Unknown:
		return theme.ColorActivityNeutral
	Loading bool
	Width   int
	Visible int
}

// Layout holds column widths in cells.
type Layout struct{ Marker, Name, Alias, Desc int }

// Pair is a foreground/background combination the list paints.
type Pair struct {
	Name   string
	Fg, Bg lipgloss.Color
}

// Layout constants, in cells. The widths below are the whole grid: a line is
// a border, a one-cell margin, the columns, then fill up to the other border.
const (
	margin        = 1
	markerWidth   = 2
	minDescWidth  = 20
	minAliasWidth = 34 // narrowest terminal that still shows the alias column

// look is one foreground/background combination, read from the theme at call
// time so that a theme applied after start-up is honored.
type look struct {
	name string
	fg   lipgloss.Color
	bg   lipgloss.Color
	bold bool
}

func (k look) style() lipgloss.Style {
	for i := 0; i < headerMinHeight; i++ {
		if i < len(info) {
			// Pad key to maxKeyLen so all ": " align
			paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
			label := theme.HeaderKeyStyle.Render(paddedKey + ": ")

			value := info[i].Value
			if info[i].Style.GetForeground() != lipgloss.Color("") {
				value = info[i].Style.Background(theme.ColorBackground).Render(value)
			} else {
				value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
			}

