// TrueColor is a no-op kept for its callers.
func TrueColor(t interface {
	Helper()
	Cleanup(func())
}) {
	t.Helper()
}

// Force is a no-op kept for TestMain callers; the returned func does nothing.
func Force() (restore func()) {
	return func() {}
}
EOF
